import { cn } from '@/lib/utils'

const WIDTHS = [160, 320, 640, 960] as const

/**
 * Responsive artwork. `src` is the asset key (e.g. /nfts/emerald-ape); the
 * WebP renditions are generated by scripts/optimize-images.mjs.
 * Width/height are always set so the browser reserves space (no CLS).
 */
export function NftImage({
  src,
  alt,
  sizes,
  priority = false,
  className,
  width = 640,
  height = 640,
}: {
  src: string
  alt: string
  sizes: string
  priority?: boolean
  className?: string
  width?: number
  height?: number
}) {
  return (
    <img
      src={`${src}-640.webp`}
      srcSet={WIDTHS.map((w) => `${src}-${w}.webp ${w}w`).join(', ')}
      sizes={sizes}
      alt={alt}
      width={width}
      height={height}
      loading={priority ? 'eager' : 'lazy'}
      fetchPriority={priority ? 'high' : 'auto'}
      decoding={priority ? 'sync' : 'async'}
      className={cn('object-cover', className)}
    />
  )
}
